import (
    "errors"
    "fmt"
)

func diviser(a, b float64) (float64, error) {
    if b == 0 {
        return 0, errors.New("division par zéro")
    }
    return a / b, nil
}

func main() {
    r, err := diviser(10, 0)
    if err != nil {
        fmt.Println("erreur :", err)
    }
    fmt.Println(r)
}

type Forme interface {
    Aire() float64
}

type Cercle struct {
    R float64
}

func (c Cercle) Aire() float64 {
    return 3.14159 * c.R * c.R
}

func total(formes []Forme) float64 {
    var t float64
    for _, f := range formes {
        t += f.Aire()
    }
    return t
}

func somme(t []int, c chan<- int) {
    total := 0
    for _, v := range t {
        total += v
    }
    c <- total
}

func main() {
    c := make(chan int)
    go somme([]int{1, 2, 3}, c)
    go somme([]int{4, 5}, c)
    a, b := <-c, <-c
    fmt.Println(a + b) // 15
}

func sante(w http.ResponseWriter, r *http.Request) {
    if r.Method != http.MethodGet {
        http.Error(w, "méthode non autorisée", http.StatusMethodNotAllowed)
        return
    }
    w.Header().Set("Content-Type", "application/json")
    io.WriteString(w, `{"statut":"ok"}`)
}

func main() {
    http.HandleFunc("/sante", sante)
    http.ListenAndServe(":8080", nil)
}

func TestSante(t *testing.T) {
    req := httptest.NewRequest(http.MethodGet, "/sante", nil)
    rec := httptest.NewRecorder()
    sante(rec, req)
    if rec.Code != http.StatusOK {
        t.Fatalf("statut attendu 200, obtenu %d", rec.Code)
    }
}
